import java.io.*;
import java.util.*;

public class G {

    void submit() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int s = sc.nextInt() - 1;
        long t = sc.nextLong();
        System.out.println(solve(n, k, s, t) + 1);
        sc.close();
    }

    int solve(int n, int k, int s, long t) {
        while (t % n != 0) {
            int delta = (s < k ? 1 : -1) * (int) (t % n);
            s = (s + n + delta) % n;
            t--;
        }
        t /= n;
        long[] when = new long[n];
        Arrays.fill(when, -1);
        for (long left = t; left > 0; left--) {
            if (when[s] != -1) {
                long period = when[s] - left;
                for (int i = 0; i < n; i++) {
                    if (when[i] != -1 && when[i] <= when[s] && when[i] % period == 0) {
                        return i;
                    }
                }
                throw new AssertionError();
            }
            when[s] = left;
            for (int i = n - 1; i > 0; i--) {
                if (s < k) {
                    s += i;
                    if (s >= n) s -= n;
                } else {
                    s -= i;
                    if (s < 0) s += n;
                }
            }
        }
        return s;
    }

    int go(int n, int m) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = i;
        for (int i = n - 1; i > 0; i--) {
            for (int j = 0; j < n; j++) {
                int delta = a[j] < m ? 1 : -1;
                a[j] = (a[j] + n + i * delta) % n;
            }
        }
        return maxDepth(a);
    }

    int maxDepth(int[] p) {
        int n = p.length;
        int ret = 0;
        int[] used = new int[n];
        Arrays.fill(used, -1);
        for (int i = 0; i < n; i++) {
            int v = i, count = 0;
            while (used[v] != i) {
                used[v] = i;
                v = p[v];
                count++;
            }
            ret = Math.max(ret, count);
        }
        return ret;
    }

    void test() {
        for (int s = 0; s < 65536; s++) {
            System.err.println(solve(65536, 1, s, 1_000_000_000_000L));
        }
    }

    void stress() {
        int tst = 0;
        while (true) {
            System.err.println(tst++);
        }
    }

    public static void main(String[] args) {
        new G().run();
    }

    void run() {
        submit();
    }
}
